<?php declare(strict_types=1);
require __DIR__.'/bootstrap.php';require __DIR__.'/app/Results/TrackingStore.php';
use App\Auth;use App\Database;use App\Repository;use App\Results\TrackingStore;Auth::requireLogin();$pdo=Database::pdo();$notice=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{Auth::verifyCsrf($_POST['csrf']??null);$pdo->exec("CREATE TABLE IF NOT EXISTS result_tracking_settings(id TINYINT PRIMARY KEY,enabled TINYINT NOT NULL DEFAULT 0,scope VARCHAR(16) NOT NULL DEFAULT 'all',check_results TINYINT NOT NULL DEFAULT 0,daily_report TINYINT NOT NULL DEFAULT 0,report_time TIME NOT NULL DEFAULT '00:00:00',report_chat VARCHAR(255) NOT NULL DEFAULT '',test_mode TINYINT NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)");$pdo->exec("INSERT IGNORE INTO result_tracking_settings(id) VALUES(1)");$q=$pdo->prepare("UPDATE result_tracking_settings SET enabled=?,scope=?,check_results=?,daily_report=?,report_time=?,report_chat=?,test_mode=? WHERE id=1");$q->execute([isset($_POST['enabled'])?1:0,$_POST['scope']==='selected'?'selected':'all',isset($_POST['check_results'])?1:0,isset($_POST['daily_report'])?1:0,preg_match('/^\d{2}:\d{2}$/',(string)$_POST['report_time'])?$_POST['report_time'].':00':'00:00:00',trim((string)$_POST['report_chat']),isset($_POST['test_mode'])?1:0]);$pdo->exec("CREATE TABLE IF NOT EXISTS result_tracking_rules(rule_id BIGINT PRIMARY KEY,enabled TINYINT NOT NULL DEFAULT 0)");$pdo->exec("DELETE FROM result_tracking_rules");$ins=$pdo->prepare("INSERT INTO result_tracking_rules(rule_id,enabled) VALUES(?,1)");foreach((array)($_POST['rules']??[]) as $id)$ins->execute([(int)$id]);$notice='Configuração de resultados atualizada.';}catch(Throwable $e){$error='Não foi possível salvar a configuração.';}}
$s=TrackingStore::settings();$rules=Repository::allRules();$selected=[];try{$selected=array_map('intval',$pdo->query("SELECT rule_id FROM result_tracking_rules WHERE enabled=1")->fetchAll(PDO::FETCH_COLUMN));}catch(Throwable){}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resultados · Telegram Router</title><link rel="stylesheet" href="/assets/saas.css"></head><body><main class="saas-content" style="max-width:980px;margin:auto"><div class="saas-heading"><div><span class="saas-kicker">RESULTADOS</span><h1>Acompanhamento automático</h1><p>O módulo é independente do encaminhamento. Desativado, não consulta a API nem interfere nos cards.</p></div><a class="saas-secondary" href="/">← Painel</a></div><?php if($notice):?><div class="saas-flash success"><?=h($notice)?></div><?php endif;?><?php if($error):?><div class="saas-flash error"><?=h($error)?></div><?php endif;?><section class="saas-card"><form method="post"><input type="hidden" name="csrf" value="<?=h(Auth::csrf())?>"><div class="treatment-checks"><label><input type="checkbox" name="enabled" <?=!empty($s['enabled'])?'checked':''?>> Ativar acompanhamento</label><label><input type="checkbox" name="check_results" <?=!empty($s['check_results'])?'checked':''?>> Verificar resultados automaticamente</label><label><input type="checkbox" name="daily_report" <?=!empty($s['daily_report'])?'checked':''?>> Relatório diário</label><label><input type="checkbox" name="test_mode" <?=!empty($s['test_mode'])?'checked':''?>> Modo de teste (não publica relatório)</label></div><div class="saas-form-grid"><label>Escopo<select name="scope"><option value="all" <?=$s['scope']==='all'?'selected':''?>>Todos os canais</option><option value="selected" <?=$s['scope']==='selected'?'selected':''?>>Somente selecionados</option></select></label><label>Horário do relatório<input type="time" name="report_time" value="<?=h(substr((string)$s['report_time'],0,5))?>"></label><label class="field-wide">Canal do relatório<input name="report_chat" value="<?=h($s['report_chat'])?>" placeholder="@canal ou -100..."></label></div><h3>Canais/regras acompanhados</h3><?php foreach($rules as $r):?><label style="display:block;margin:8px 0"><input type="checkbox" name="rules[]" value="<?=h($r['id'])?>" <?=in_array((int)$r['id'],$selected,true)?'checked':''?>> <?=h($r['source_chat'])?> → <?=h($r['destination_chat'])?></label><?php endforeach;?><div class="saas-actions"><button class="saas-primary">Salvar configurações</button></div></form></section></main></body></html>